sys_script_include.script:
var LoanerRequestUtils = Class.create();
LoanerRequestUtils.prototype = {
    initialize: function() {
        this.pickupLeadTime = gs.getProperty('x_cdltd_loaner_r_0.pickup.leadtime');
    },

    getNullPickupReminders: function() {
        var loanerGr = new GlideRecord('x_cdltd_loaner_req_loaner_request');
        loanerGr.addQuery('state', 16);
        loanerGr.addNullQuery('pick_up_reminder');
        loanerGr.query();

        return loanerGr;
    },

    sendPickupReminder: function(loanerGr) {
        loanerGr.pick_up_reminder = new GlideDateTime();
        loanerGr.update();

        gs.eventQueue(
            'x_cdltd_loaner_req.pickUp',
            loanerGr,
            loanerGr.requested_for,
            loanerGr.number
        );
    },

    type: 'LoanerRequestUtils'
};
